lessons.content:
h1 { color: blue; }
.title { font-size: 20px; }
#header { background-color: lightgray; }

/* Descendant Selector */
div p {
  color: green;
}

/* Child Selector */
div > p {
  color: red;
}

/* Adjacent sibling */
h1 + p {
  font-style: italic;
}

/* General sibling */
h1 ~ p {
  color: purple;
}
